@@ -0,0 +1,15 @@
+name: crypt
+description: "Dungeon chiptune: a vibrato pulse lead, soft and thin pulses, triangle bass, dry noise drums and a low tom."
+instruments:
+  p: { name: pulse_lead, osc: pulse, duty: 0.25, env: [0.004, 0.1, 0.6, 0.14], vibrato: [5.0, 0.15, 0.2], gain: -7, range: [C4, C7] }
+  q: { name: pulse_soft, osc: pulse, duty: 0.5, env: [0.01, 0.15, 0.4, 0.12], gain: -11, range: [C3, C6] }
+  r: { name: pulse_thin, osc: pulse, duty: 0.125, env: [0.002, 0.06, 0.4, 0.06], gain: -10, range: [C3, C7] }
+  b: { name: tri_bass, osc: triangle, env: [0.002, 0.05, 0.95, 0.05], gain: -2, range: [E1, C4] }
+  k: { name: kick, drum: kick, tune: 48, decay: 0.25, gain: -2 }
+  s: { name: rim, drum: snare, tune: 220, noise: 0.55, decay: 0.1, tone: 2600, gain: -7 }
+  h: { name: hat, drum: hat, decay: 0.03, gain: -15 }
+  t: { name: low_tom, drum: tom, tune: 90, decay: 0.3, gain: -6 }
+groups:
+  leads: [p, q, r]
+  bass: [b]
+  drums: [k, s, h, t]
